import {archiveAvailable,archiveObjective,ARCHIVE_ENCOUNTERS,ARCHIVE_LOADOUTS} from './archive.js?v=0.13.3';
import {REGIONS} from './regions.js?v=0.13.3';
import {ROOMS} from './indoors.js?v=0.13.3';
export function createArchiveUI({getState,world,run,openModal,closeModal,button,waterUI,mark}){
 const s=()=>getState(),a=()=>s().archive,panel=(title,html)=>openModal('archive','封存库的回声 / 可选巡查',title,html),actions=x=>`<div class="action-list">${x}</div>`;
 const next=()=>{closeModal();mark();};
 function journalHTML(){const q=archiveObjective(s());return `<div class="current-wish"><h3>${q.title}</h3><p>${q.body}</p><ul>${q.checks.map(([label,done])=>`<li class="${done?'done':''}">${done?'✓':'□'} ${label}</li>`).join('')}</ul></div><p>没有期限。已完成的段落会保留，撤退不掉财物。村井仍是清水，庄园与温室照常经营。</p>${a().cleared?'<p>✓ 附录：一笔从未兑现的清运工钱</p>':''}${a().reported?'<div class="archive-keepsake"><span class="archive-badge" role="img" aria-label="巡查徽记"></span><p>巡查徽记 · 清单上，每个人都有名字。<br>80金币已领取；外渠工具箱开放三种免费配置。</p></div>':''}${actions(button('标记封存调查下一步',next,{primary:true})+button('继续生活',closeModal))}`;}
 function board(){panel('一份未签完的清单',()=>`<p>陶恩把最后一栏划了两次：“旧井已经干净，但当年的清运单没写完。”米菈补上巡查员岑禾的名字。她进了旧染坊外渠，还没有回来。</p><p>北闸和封存库是两处旧设施。这里调查的是遗留封存物，不会让已经治好的村民再次感染。</p>${a().sealed?'<p>岑禾的记录和账册已经齐全。陶恩负责复查铜管，米菈核对清运名单。这一次，每个签名都有人回应。</p>':''}${actions(!a().started?button('接下封存清单',()=>{if(run('archiveStart')){mark();board();}},{primary:true,disabled:archiveAvailable(s())?'':'完成公共夜市，并交回水源报告'}):a().sealed&&!a().reported?button('交回清单，领取巡查徽记',()=>{if(run('archiveReport'))board();},{primary:true,small:'80金币 · 纪念与新配置 · 只领取一次'}):'')}${journalHTML()}`);}
 function camp(){panel('岑禾留下的工具箱',()=>`<p>“先点齐人数，再算清货物。”巡查笔记翻在这一页。左边是仓库，右边是封存机房。每一段都可单独准备、单独撤回。</p>${!a().briefed?actions(button('读完巡查记录',()=>{if(run('archiveBrief'))camp();},{primary:true})): '<p>仓库安全路线：<strong>东通风窗 → 北货架 → 西锁扣</strong>。关阀顺序：<strong>西 → 南 → 东</strong>。</p>'}<p>短剑、提灯和两份绷带每场重新备齐。战斗不扣种田体力；每次进入推进10分钟。</p>${a().reported?`<h3>下次巡查的配置</h3>${actions(Object.entries(ARCHIVE_LOADOUTS).map(([key,v])=>button((a().loadout===key?'✓ ':'')+v.name,()=>{if(run('archiveLoadout',{key}))camp();},{small:v.text,disabled:a().loadout===key?'已采用':''})).join(''))}`:''}${actions(button('战斗辅助：'+(s().water.assist?'开启':'关闭'),()=>{if(run('waterAssist'))camp();},{small:'预警更长、来伤更低，剧情奖励相同'})+button('查看下一步',()=>panel('封存调查手记',journalHTML))+button('准备好了，继续走',closeModal,{primary:true}))}`);}
 function start(encounter,practice=false){if(!run('archiveFight',{encounter,practice}))return;waterUI.startOperation(a().pending,(b,won)=>{const ok=won?run('archiveFinish',{id:b.id,encounter:b.encounter,won:true}):run('archiveRetreat');if(!ok)return;panel(won?'灯光停稳了':'先回安全的地方',()=>`<p>${!won?'你退回了本段入口。已救回的人、账册和完成节点都保留。生命、耐力、绷带和设备将在下次开始时重新备齐。':practice?'这次演练结束。金币、徽记和调查进度没有变化。':encounter==='canalRescue'?'岑禾扶着墙站起来：“谢谢。我得把点名簿带回去——可不能把自己漏在上面。”她把仓库钥匙交给你，提醒你从东通风窗开始。':encounter==='storeClear'?'黑苔消散，货签上的一笔欠款露了出来。附录记进手记，现在可到北墙账桌取账册。':'西、南、东三个阀门归位。封存灯稳定亮起，剩余孢子失去活性。回广场交回清单，给每个人一个交代。'}</p><p class="small-note">本次压制 ${b.kills} · ${encounter==='sealDevice'?'关阀 '+b.operation.valves.filter(v=>v.closed).length+'/3 · 装置 '+Math.ceil(b.pump.hp)+'/'+b.pump.max:'两批遭遇'}</p>${actions(button('记下下一步',next,{primary:true})+button('留在这里走走',closeModal))}`);});}
 function fight(encounter){const m=ARCHIVE_ENCOUNTERS[encounter],done=a()[m.flag],practice=encounter==='sealDevice'&&a().reported;
 panel(m.name,()=>`<p>${encounter==='canalRescue'?(done?'岑禾：“仓库有安全侧路。先打开东通风窗，再查看北货架，最后拉开西锁扣。别硬撑，灯不该只照着账册。”':'岑禾坐在墙边，黑苔封住了退路。靠近后会有两批附着物，各3个；清完两批，她就能脱身。'):encounter==='storeClear'?'这里封着两批黑苔，每批4个。清理可直接打开账桌并发现清运附录；也可以按东窗、北架、西扣安全取证。两种路线都能推进调查。':'装置需要隔离三条支管。靠近当前阀门按 E，静止2秒完成关闭；移动、受伤、挥剑、闪避或提灯会中断。前两次关阀后各预警下一批4个敌人，第三阀关闭即完成封存。'}</p>${encounter==='sealDevice'?'<p>装置生命240（加固300）。敌人会分头逼近你和装置。Q震退可争取关阀时间；巡查册 C 内有3次修理，每次恢复45。Esc随时暂停或撤退。</p>':''}<p>空格挥剑 · Shift闪避 · Q震退 · R绷带 · C巡查册 · Esc暂停</p>${actions(button(practice?'开始无奖演练':'准备好了，开始'+m.name,()=>start(encounter,practice),{primary:true,disabled:done&&!practice?'这一段已经完成':!a().briefed?'先读外渠工具箱记录':''})+button('先继续调查',closeModal))}`);
 }
 function handle(target){const id=target.id;
 if(id==='archiveCamp'){camp();return true;}
 if(id==='patroller'){fight('canalRescue');return true;}
 if(id==='archiveCache'){fight('storeClear');return true;}
 if(id==='sealConsole'){fight('sealDevice');return true;}
 if(['archiveDoor','sealDoor'].includes(id)){const room=id==='archiveDoor'?'archiveRoom':'sealRoom';panel(ROOMS[room].name,()=>`<p>${room==='archiveRoom'?'岑禾保管着仓库钥匙。里面有安全取证路线，也可主动清理黑苔。':'账册记着机房的封存顺序。准备好后，再主动启动设备。进入房间不会自动开战。'}</p>${actions(button('推门进去',()=>{if(run('enterRoom',{room}))closeModal();},{primary:true,disabled:room==='archiveRoom'&&!a().rescued?'先救回门外的岑禾':room==='sealRoom'&&!a().ledger?'先找到封存账册':''})+button('先在外渠走走',closeModal))}`);return true;}
 const index=['archiveWindow','archiveShelf','archiveLatch'].indexOf(id);if(index>=0){panel(target.name,()=>`<p>${['推开高处通风窗，让旧布上的灰慢慢落下。','北货架留下三张货签，编号通向西边的锁扣。','西扣松开后，北墙账桌的侧面可以安全打开。'][index]}</p><p>顺序：东窗 → 北架 → 西扣。当前 ${a().routeStep}/3；选错顺序可免费重试。</p>${actions(button('检查这个节点',()=>{if(run('archiveRoute',{index}))handle(target);},{primary:true,disabled:a().routeStep===3?'安全路线已完成':''})+button('继续查看下一处',closeModal))}`);return true;}
 if(id==='archiveLedgerSpot'){panel('封存账册',()=>`<p>账页停在清运日期前一天：“暂存在北闸，待新库腾空后转入。”下一页却没有收讫签名。机房记录注明：先西阀，再南阀，最后东阀。</p>${actions(button('将账册收进手记',()=>{if(run('archiveLedger')){closeModal();mark();}},{primary:true,disabled:a().ledger?'账册已收好':a().routeStep!==3&&!a().cleared?'先完成安全路线，或清理仓库':''})+button('再看看仓库',closeModal))}`);return true;}return false;}
 return {board,handle,journalHTML};
}
